import React from 'react';
import clx from 'classnames';
import styles from './table.module.scss';

interface TableProps {
  headerColumns: string[];
  dataSource: string[][];
  headerRow: string[];
  mode: 'dark' | 'light';
  onlyTextTable?: boolean;
}

const CELL_WEIGHT = 136;
let scrollTimeout: NodeJS.Timeout;

const Table = (props: TableProps) => {
  const { headerColumns, dataSource, headerRow, mode = 'light', onlyTextTable } = props;

  const [scrollbarNotStart, setScrollbarNotStart] = React.useState(false);

  const handleScroll = (event: React.UIEvent<HTMLDivElement>) => {
    const left = event.currentTarget.scrollLeft;
    clearTimeout(scrollTimeout);
    scrollTimeout = setTimeout(() => {
      setScrollbarNotStart(left > CELL_WEIGHT / 2);
    }, 150);
  };

  // 在组件挂载后设置初始滚动位置
  const tableRef = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    if (tableRef.current) {
      tableRef.current.scrollLeft = 0;
    }
  }, []);

  return (
    <React.Fragment>
      <div
        ref={tableRef}
        onScroll={handleScroll}
        className={clx(
          mode === 'dark' && 'dark-theme',
          styles.tableScrollWrapper,
          scrollbarNotStart && styles.scrolling,
          onlyTextTable && styles.onlyTextTable
        )}
      >
        <table>
          <thead className={styles.headerColumn}>
            <tr>
              <th></th>
              {headerColumns.map((headerColumn: string, index) => (
                <th key={index}>{headerColumn}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {dataSource?.map((row: string[], index: number) => (
              <tr key={index} className={styles.row}>
                <th>{headerRow[index]}</th>
                {row.map((cell: string, cellIdx) => (
                  <td key={cellIdx} className={styles['table-cell']}>
                    {cell}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </React.Fragment>
  );
};

export default Table;

export { Table };

